  "Turn a complex battle script into a cinematic sequence": { es: "Convierte un guion de batalla complejo en una secuencia cinematográfica", "zh-CN": "把复杂的战斗脚本变成电影感片段", "zh-TW": "把複雜的戰鬥腳本變成電影感片段" },
  "Guide your character through a connected visual journey": { es: "Guía a tu personaje en un viaje visual conectado", "zh-CN": "引导角色完成一段连贯的视觉旅程", "zh-TW": "引導角色完成一段連貫的視覺旅程" },
  "Build Suspense with Multiple Characters": { es: "Crea suspense con varios personajes", "zh-CN": "用多个角色营造悬念", "zh-TW": "用多個角色營造懸念" },
  "Keep Your Character Consistent Across Every Scene": { es: "Mantén tu personaje coherente en todas las escenas", "zh-CN": "让角色在每个场景中保持一致", "zh-TW": "讓角色在每個場景中保持一致" },
  "Show a multi-step process with clear action": { es: "Muestra un proceso de varios pasos con acciones claras", "zh-CN": "清晰展示多步骤流程", "zh-TW": "清晰展示多步驟流程" },
  "Adapt one product idea for the channel": { es: "Adapta una idea de producto al canal", "zh-CN": "为不同渠道调整一个产品创意", "zh-TW": "為不同渠道調整一個產品創意" },
  "Shot planning": { es: "Planificación de planos", "zh-CN": "镜头规划", "zh-TW": "鏡頭規劃" },
