  "Character consistency": { es: "Coherencia de personajes", "zh-CN": "人物一致性", "zh-TW": "人物一致性" },
  "Multi-scene continuity": { es: "Continuidad entre escenas", "zh-CN": "多场景连续性", "zh-TW": "多場景連貫性" },
  "Process video": { es: "Vídeo de procesos", "zh-CN": "流程视频", "zh-TW": "流程影片" },
